import test from 'node:test'
import assert from 'node:assert/strict'
import { inspectColors, applyExceptions, classifyColorData } from '../../scripts/ui/colors.mjs'

test('UI-LITERAL-SYNTAX: HEX rgb hsl named and inline values fail; comments and identifiers do not', () => {
  const css =
    '/* color: red */ .x { background: #123456; border: 1px solid rgb(1,2,3); color: hsl(0 0% 0%); box-shadow: 0 0 white; white-space: nowrap }'
  const hits = inspectColors('feature.css', css)
  assert.deepEqual(
    hits.map((h) => h.value),
    ['#123456', 'rgb(1,2,3)', 'hsl(0 0% 0%)', 'white'],
  )
  assert.equal(
    inspectColors('feature.tsx', 'const el=<div style={{color: "red", background:"#abcdef"}} />')
      .length,
    2,
  )
  assert.equal(
    inspectColors('feature.css', '.x {color: var(--frade-text-primary); background: Canvas}')
      .length,
    0,
  )
  assert.equal(
    inspectColors('feature.ts', '// "#abcdef"\nconst red = "redemption"; const x = /#[a-f]{6}/')
      .length,
    0,
  )
})
test('UI-LITERAL-LEGACY: adding new color beside an exact legacy occurrence fails', () => {
  const file = 'feature.css',
    old = '.x { color: #123456; }'
  const legacy = inspectColors(file, old).map((h) => ({
    ...h,
    reason: 'preexisting baseline',
    stage: 'shell',
    classification: 'LEGACY',
  }))
  assert.deepEqual(applyExceptions(inspectColors(file, old), legacy), [])
  const added = old + '\n.y { color: #abcdef }'
  const errors = applyExceptions(inspectColors(file, added), legacy)
  assert.equal(errors.length, 1)
  assert.match(errors[0], /abcdef/)
  assert.notEqual(
    applyExceptions(inspectColors(file, old.replace('123456', '654321')), legacy).length,
    0,
  )
})
test('UI-LITERAL-EXCEPTIONS: moved/context-changed/duplicate or blanket exceptions fail', () => {
  const hits = inspectColors('feature.css', '.x { color:#123456 }')
  assert.notEqual(applyExceptions(hits, [{ file: 'feature.css', reason: 'entire file' }]).length, 0)
  const entry = { ...hits[0], reason: 'baseline', stage: 'shell', classification: 'LEGACY' }
  assert.notEqual(applyExceptions(hits, [entry, entry]).length, 0)
  assert.notEqual(
    applyExceptions(inspectColors('feature.css', '\n.x { color:#123456 }'), [entry]).length,
    0,
  )
})
test('UI-LITERAL-DATA: validated theme/domain/generated boundaries are distinct', () => {
  assert.equal(
    classifyColorData('theme', { kind: 'dark', colors: { 'focus.ring': '#123456' } }).length,
    0,
  )
  assert.notEqual(
    classifyColorData('theme', { kind: 'dark', colors: { invented: '#123456' } }).length,
    0,
  )
  assert.equal(
    classifyColorData('domain-paint', { fill: '#abcdef', stroke: '#123456', width: 1 }).length,
    0,
  )
  assert.notEqual(
    classifyColorData('domain-paint', { fill: 'url(javascript:evil)', width: 1 }).length,
    0,
  )
  assert.notEqual(classifyColorData('unknown', {}).length, 0)
})

import { checkDrawioEditor, drawioGeneratedPaths } from './drawio-editor-style.mjs'
import { createRequire } from 'node:module'
import { readFile, readdir } from 'node:fs/promises'
import { createHash } from 'node:crypto'
import { resolve, extname } from 'node:path'
import { fileURLToPath } from 'node:url'
import { root, themeRoles } from './tokens.mjs'
import {
  checkReferenceFiles,
  generatedPath as referenceGeneratedPath,
} from './vscode-dark-2026.mjs'
const require = createRequire(resolve(root, 'packages/ui-workspace/package.json'))
const ts = require('typescript')
const names =
  'aliceblue antiquewhite aqua aquamarine azure beige bisque black blanchedalmond blue blueviolet brown burlywood cadetblue chartreuse chocolate coral cornflowerblue cornsilk crimson cyan darkblue darkcyan darkgoldenrod darkgray darkgrey darkgreen darkkhaki darkmagenta darkolivegreen darkorange darkorchid darkred darksalmon darkseagreen darkslateblue darkslategray darkslategrey darkturquoise darkviolet deeppink deepskyblue dimgray dimgrey dodgerblue firebrick floralwhite forestgreen fuchsia gainsboro ghostwhite gold goldenrod gray grey green greenyellow honeydew hotpink indianred indigo ivory khaki lavender lavenderblush lawngreen lemonchiffon lightblue lightcoral lightcyan lightgoldenrodyellow lightgray lightgrey lightgreen lightpink lightsalmon lightseagreen lightskyblue lightslategray lightslategrey lightsteelblue lightyellow lime limegreen linen magenta maroon mediumaquamarine mediumblue mediumorchid mediumpurple mediumseagreen mediumslateblue mediumspringgreen mediumturquoise mediumvioletred midnightblue mintcream mistyrose moccasin navajowhite navy oldlace olive olivedrab orange orangered orchid palegoldenrod palegreen paleturquoise palevioletred papayawhip peachpuff peru pink plum powderblue purple rebeccapurple red rosybrown royalblue saddlebrown salmon sandybrown seagreen seashell sienna silver skyblue slateblue slategray slategrey snow springgreen steelblue tan teal thistle tomato turquoise violet wheat white whitesmoke yellow yellowgreen transparent'.split(
    ' ',
  )
const colorPattern = new RegExp(
  '#[\\da-f]{3,8}(?![\\da-f])|(?:rgba?|hsla?)\\([^)]*\\)|(?<![\\w-])(?:' +
    names.join('|') +
    ')(?![\\w-])',
  'gi',
)
const sha = (s) => createHash('sha256').update(s).digest('hex')
export function inspectColors(file, original) {
  const source = original.replaceAll('\r\n', '\n')
  const hits = []
  const collect = (value, base, literalEnd) => {
    for (const match of value.matchAll(colorPattern)) {
      const start = base + match.index,
        end = literalEnd ?? start + match[0].length
      const lineStart = source.lastIndexOf('\n', base - 1) + 1
      const lineEnd = source.indexOf('\n', base)
      const context = source.slice(lineStart, lineEnd < 0 ? source.length : lineEnd)
      hits.push({
        file: file.replaceAll('\\', '/'),
        start,
        end,
        line: source.slice(0, start).split('\n').length,
        value: match[0],
        occurrenceHash: sha(match[0] + '\n' + context),
        context,
      })
    }
  }
  if (extname(file) === '.css') {
    const clean = source.replace(/\/\*[\s\S]*?\*\//g, (text) => text.replace(/[^\n]/g, ' '))
    for (const declaration of clean.matchAll(/[-\w]+\s*:\s*([^;{}]+)/g)) {
      const value = declaration[1]
      collect(value, declaration.index + declaration[0].indexOf(value))
    }
  } else {
    const ast = ts.createSourceFile(
      file,
      source,
      ts.ScriptTarget.Latest,
      true,
      extname(file) === '.tsx' ? ts.ScriptKind.TSX : ts.ScriptKind.TS,
    )
    const visit = (node) => {
      if (
        ts.isStringLiteralLike(node) ||
        ts.isTemplateHead(node) ||
        ts.isTemplateMiddle(node) ||
        ts.isTemplateTail(node)
      )
        collect(node.text, node.getStart(ast) + 1, node.getEnd())
      ts.forEachChild(node, visit)
    }
    visit(ast)
  }
  return hits.sort((a, b) => a.start - b.start)
}
const key = (h) => [h.file, h.start, h.end, h.value, h.occurrenceHash].join('\0')
export function applyExceptions(hits, exceptions) {
  const errors = [],
    allowed = new Set()
  for (const entry of exceptions) {
    if (
      !entry.reason ||
      !entry.stage ||
      !['LEGACY', 'DOMAIN_VISUALIZATION', 'BRAND'].includes(entry.classification) ||
      !Number.isInteger(entry.start) ||
      !Number.isInteger(entry.end) ||
      !entry.value ||
      !/^[a-f\d]{64}$/.test(entry.occurrenceHash ?? '')
    ) {
      errors.push('Invalid occurrence exception: ' + entry.file)
      continue
    }
    const id = key(entry)
    if (allowed.has(id)) errors.push('Duplicate exception: ' + entry.file + ':' + entry.start)
    allowed.add(id)
  }
  const actual = new Set(hits.map(key))
  for (const entry of exceptions)
    if (!actual.has(key(entry))) errors.push('Stale exception: ' + entry.file + ':' + entry.start)
  for (const hit of hits)
    if (!allowed.has(key(hit)))
      errors.push(hit.file + ':' + hit.line + ': forbidden color ' + hit.value)
  return errors
}
export function classifyColorData(kind, value) {
  const errors = []
  const hex = (v) =>
    typeof v === 'string' && /^#[\da-f]{6,8}$/i.test(v) && [7, 9].includes(v.length)
  if (!value || typeof value !== 'object' || Array.isArray(value))
    return ['Expected color data object']
  if (kind === 'theme') {
    if (
      !['light', 'dark', 'high-contrast'].includes(value.kind) ||
      !value.colors ||
      typeof value.colors !== 'object'
    )
      return ['Invalid theme boundary']
    for (const [role, color] of Object.entries(value.colors))
      if (!themeRoles.includes(role) || typeof color !== 'string' || !/^#[\da-f]{6}$/i.test(color))
        errors.push('Invalid theme color ' + role)
  } else if (kind === 'domain-paint') {
    for (const [field, color] of Object.entries(value)) {
      if (['fill', 'stroke', 'color'].includes(field)) {
        if (!hex(color)) errors.push('Invalid domain paint ' + field)
      } else if (field !== 'width' || !Number.isFinite(color) || color < 0)
        errors.push('Unknown domain paint field ' + field)
    }
  } else errors.push('Unknown color data boundary ' + kind)
  return errors
}
export const featureRoots = Object.freeze([
  'apps/desktop/src/renderer',
  'packages/ui-workspace/src',
  'packages/ui-navigator/src',
  'packages/ui-inspector/src',
  'packages/draw/src',
])
export async function featureColorHits(base = root) {
  const result = []
  const walk = async (relative) => {
    for (const item of await readdir(resolve(base, relative), { withFileTypes: true })) {
      const file = relative + '/' + item.name
      if (item.isDirectory()) await walk(file)
      else if (
        /\.(css|tsx?)$/.test(file) &&
        ![
          'packages/ui-workspace/src/design/generated/tokens.css',
          'packages/ui-workspace/src/design/generated/tokens.ts',
          referenceGeneratedPath,
          ...drawioGeneratedPaths,
        ].includes(file)
      )
        result.push(...inspectColors(file, await readFile(resolve(base, file), 'utf8')))
    }
  }
  for (const directory of featureRoots) await walk(directory)
  return result
}
export async function checkFeatureColors(base = root) {
  const inventory = JSON.parse(
    await readFile(resolve(base, 'docs/ui/decisions/legacy-colors.json'), 'utf8'),
  )
  if (inventory.version !== 1 || inventory.normalization !== 'LF UTF16 logical spans')
    throw new Error('Invalid exception inventory version')
  const hits = await featureColorHits(base)
  const errors = applyExceptions(hits, inventory.occurrences)
  let verifyDrawio = resolve(base) === resolve(root)
  for (const file of [
    ...drawioGeneratedPaths,
    'packages/ui-workspace/tokens/drawio-editor-source.json',
  ]) {
    try {
      await readFile(resolve(base, file))
      verifyDrawio = true
    } catch (error) {
      if (error.code !== 'ENOENT') throw error
    }
  }
  if (verifyDrawio) errors.push(...(await checkDrawioEditor({ base })))

  // The exact generated token exemption is valid only with source-bound regeneration.
  try {
    await readFile(resolve(base, referenceGeneratedPath))
    const reference = await checkReferenceFiles(base)
    errors.push(...reference.errors)
  } catch (error) {
    if (error.code !== 'ENOENT') throw error
  }
  return {
    status: errors.length ? 'FAIL' : 'PASS',
    occurrences: hits.length,
    legacyExceptions: inventory.occurrences.length,
    errors,
  }
}
if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    const result = await checkFeatureColors(
      process.argv.includes('--root')
        ? resolve(process.argv[process.argv.indexOf('--root') + 1])
        : root,
    )
    console.log(JSON.stringify(result))
    process.exitCode = result.errors.length ? 1 : 0
  } catch (error) {
    console.error(String(error))
    process.exitCode = 1
  }
}

import { expect, it } from 'vitest'
import { createHash } from 'node:crypto'
import { existsSync, lstatSync, readFileSync, readdirSync, realpathSync } from 'node:fs'
import { resolve, relative } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = fileURLToPath(new URL('../../../../', import.meta.url))
const change = 'frade-light-diagram-editor'
const prefix = 'openspec/changes/' + change + '/'
const manifestPath = prefix + 'evidence/upstream-bdd-bindings-20261026/bindings-manifest-portability.json'
const manifestSha256 = '2bec063e00f7d6589f3e1f7c60c1f9ee98659aefca8d3434cd66f41ef64e1b21'
const ids = Array.from({ length: 9 }, (_, i) => 'LDE-' + String(i + 1).padStart(3, '0'))
const digest = (raw: Buffer) => createHash('sha256').update(raw).digest('hex')
type Pin = { file: string; sha256: string; publishedSha256?: string }
type Binding = { id: string; cases: { report: string; title: string }[] }
type Manifest = { inputs: Pin[]; reports: Record<string, Pin & { format: 'playwright' | 'vitest' | 'tap' }>; bindings: Binding[] }
type Case = { title: string; passed: boolean }
function demand(value: unknown, error: string): asserts value {
  if (!value) throw Error(error)
}
function safeFile(file: string): Buffer {
  demand(!file.includes('\\') && !file.split('/').some(part => part === '..' || part === '.' || !part), 'UNSAFE_PATH')
  let physical = file
  if (file.startsWith(prefix)) {
    const suffix = file.slice(prefix.length)
    const archive = resolve(root, 'openspec/changes/archive')
    const candidates = [prefix + suffix, ...readdirSync(archive).filter(name => /^\d{4}-\d{2}-\d{2}-frade-light-diagram-editor$/.test(name)).map(name => 'openspec/changes/archive/' + name + '/' + suffix)].filter(name => existsSync(resolve(root, name)))
    demand(candidates.length === 1, 'EVIDENCE_LOCATION')
    physical = candidates[0]
  }
  let current = root
  for (const part of physical.split('/')) {
    current = resolve(current, part)
    demand(!lstatSync(current).isSymbolicLink(), 'UNSAFE_LINK')
  }
  demand(!relative(root, realpathSync(current)).startsWith('..') && lstatSync(current).isFile(), 'UNSAFE_FILE')
  return readFileSync(current)
}
function reportCases(format: string, raw: Buffer): Case[] {
  if (format === 'tap') {
    const text = raw.toString()
    demand(!/^not ok /m.test(text) && /^# fail 0\r?$/m.test(text) && /^# skipped 0\r?$/m.test(text), 'FAILED_TAP')
    return [...text.matchAll(/^ok \d+ - (.+)\r?$/gm)].map(m => ({ title: m[1].replace(/\r$/, ''), passed: true }))
  }
  const report = JSON.parse(raw.toString())
  if (format === 'vitest') return report.testResults.flatMap((suite: { assertionResults: { fullName: string; status: string }[] }) => suite.assertionResults.map(test => ({ title: test.fullName, passed: test.status === 'passed' })))
  const cases: Case[] = []
  const walk = (suite: { specs?: { title: string; tests: { status: string; results: { status: string; errors?: unknown[] }[] }[] }[]; suites?: typeof suite[] }) => {
    for (const spec of suite.specs ?? []) for (const test of spec.tests) cases.push({ title: spec.title, passed: test.status === 'expected' && test.results.length === 1 && test.results[0].status === 'passed' && !test.results[0].errors?.length })
    for (const child of suite.suites ?? []) walk(child)
  }
  walk(report)
  return cases
}
function verify(read = safeFile) {
  const raw = read(manifestPath)
  demand(digest(raw) === manifestSha256, 'MANIFEST_HASH')
  const manifest: Manifest = JSON.parse(raw.toString())
  demand(JSON.stringify(manifest.bindings.map(b => b.id)) === JSON.stringify(ids), 'BDD_IDS')
  for (const pin of manifest.inputs) {
    const actual = digest(read(pin.file))
    demand(actual === pin.sha256 || actual === pin.publishedSha256, 'INPUT_HASH')
  }
  const reports = new Map<string, Case[]>()
  for (const [id, pin] of Object.entries(manifest.reports)) {
    const report = read(pin.file)
    demand(digest(report) === pin.sha256, 'REPORT_HASH')
    reports.set(id, reportCases(pin.format, report))
  }
  return { manifest, reports }
}
let cached: ReturnType<typeof verify> | undefined
for (const id of ids) it(id + ' exact-source executable evidence binding', () => {
  cached ??= verify()
  const feature = safeFile(prefix + 'bdd/light-diagram-editor.feature').toString()
  expect([...feature.matchAll(/@(LDE-\d{3})/g)].map(m => m[1])).toEqual(ids)
  const binding = cached.manifest.bindings.find(b => b.id === id)!
  expect(binding.cases.length).toBeGreaterThan(0)
  for (const wanted of binding.cases) {
    const cases = cached.reports.get(wanted.report)!.filter(c => c.title === wanted.title)
    expect(cases, wanted.title).toHaveLength(1)
    expect(cases[0].passed, wanted.title).toBe(true)
  }
})
it('LDE binding rejects source and report tampering without editing evidence', () => {
  const { manifest } = verify()
  for (const target of [manifest.inputs[0].file, Object.values(manifest.reports)[0].file]) expect(() => verify(file => file === target ? Buffer.concat([safeFile(file), Buffer.from('\nmutation')]) : safeFile(file))).toThrow(target === manifest.inputs[0].file ? 'INPUT_HASH' : 'REPORT_HASH')
  expect(() => verify(file => file === manifestPath ? Buffer.from('{}') : safeFile(file))).toThrow('MANIFEST_HASH')
})

it('LDE source publication accepts only the predeclared checkout and committed byte forms', () => {
